from abc import ABC, abstractmethod
from typing import Dict, Any, Optional
from ..llm_client import LLMClient, LLMOutputInvalid

class BaseProfile(ABC):
    """Base class for classification profiles."""

    @property
    @abstractmethod
    def name(self) -> str:
        """Profile name (e.g., 'receipt')."""
        pass

    @abstractmethod
    def build_prompt(self, ocr_text: str, note_text: str, hints: Dict[str, Any]) -> str:
        """Build LLM prompt for this profile."""
        pass

    @abstractmethod
    def get_schema(self) -> Dict[str, Any]:
        """Return JSON schema for LLM structured output."""
        pass

    @abstractmethod
    def normalize(self, raw_output: Dict[str, Any], hints: Dict[str, Any]) -> Dict[str, Any]:
        """
        Apply post-processing to LLM output:
        - Slugification
        - Tag generation
        - Fallback values
        - Filename construction
        """
        pass

    def _add_error_context(self, prompt: str, raw_output: Any, error: Exception) -> str:
        """Optional: Enchance prompt with error info."""
        return f"{prompt}\n\nPrevious attempt failed. Error: {str(error)}. Please fix the JSON."

    def classify(self, llm_client: LLMClient, ocr_text: str, note_text: str = "", hints: Dict[str, Any] = None) -> Dict[str, Any]:
        """
        Main classification flow (same for all profiles).

        1. Build prompt
        2. Call LLM with retries
        3. Normalize output
        4. Return result
        """
        hints = hints or {}
        prompt = self.build_prompt(ocr_text, note_text, hints)
        schema = self.get_schema()

        last_error = None
        # Retry logic
        for attempt in range(3):
            try:
                raw = llm_client.classify(prompt, schema)
                return self.normalize(raw, hints)
            except LLMOutputInvalid as e:
                last_error = e
                if attempt == 2:
                    raise
                # Update prompt with feedback (simple append for now)
                prompt = self._add_error_context(prompt, None, e)
            except Exception as e:
                # Retrying other errors might depend on the error type
                # For V1 we assume LLMServiceError is retried by the client logic or we fail fast here
                # Let's retry generic errors too just in case
                last_error = e
                if attempt == 2:
                    raise
        raise last_error

